def _discovery_client(cache_control: Any) -> MagicMock:
    mock_client = MagicMock()
    headers = {"content-type": "application/json"}
    if cache_control is not None:
        headers["cache-control"] = cache_control
    mock_client.send_request.return_value = ApiHttpResponse(
        status_code=200,
        body=json.dumps(
            {
                "authorization_endpoint": "https://auth.example.com/authorize",
                "token_endpoint": "https://auth.example.com/token",
            }
        ),
        headers=headers,
    )
    return mock_client


class TestDiscoveryCacheLifetime:
    @pytest.mark.parametrize(
        ("headers", "expected"),
        [
            ({"Cache-Control": "max-age=120"}, 120),
            ({"cache-control": "public, MAX-AGE=45"}, 45),
            ({"Cache-Control": "max-age=0"}, 0),
            ({"Cache-Control": "max-age=9999999999"}, 31536000),
            ({"Cache-Control": "no-store"}, 86400),
            ({"Cache-Control": "max-age=abc"}, 86400),
            ({"content-type": "application/json"}, 86400),
            ({}, 86400),
            (None, 86400),
        ],
    )
    def test_max_age_is_read_from_the_cache_control_header(
        self, headers: Any, expected: int
    ) -> None:
        from petstore_client.auth.oauth.openid_connect_authenticator import (
            _parse_max_age,
        )

        assert _parse_max_age(headers) == expected

    def test_rediscovery_after_expiry_keeps_the_exchanged_session(self) -> None:
        from unittest.mock import patch

        auth = _create_authenticator()
        mock_client = _discovery_client("max-age=100")
        discovery = mock_client.send_request.return_value

        def respond(
            method: str, url: str, *args: Any, **kwargs: Any
        ) -> ApiHttpResponse:
            if url.endswith("openid-configuration"):
                return discovery
            return ApiHttpResponse(
                status_code=200,
                body=json.dumps(
                    {"access_token": "at-1", "token_type": "Bearer", "expires_in": 3600}
                ),
                headers={"content-type": "application/json"},
            )

        mock_client.send_request.side_effect = respond
        auth.set_api_client(mock_client)
        module = "petstore_client.auth.oauth.openid_connect_authenticator.time"

        with patch(module) as clock:
            clock.monotonic.return_value = 1000.0
            auth.exchange_code("the-code")
            clock.monotonic.return_value = 1100.0
            # The cached document has expired: it is fetched again, and the code
            # exchange made before it must still count.
            assert auth.get_auth_headers() == {"Authorization": "Bearer at-1"}

    def test_a_document_is_refetched_once_its_max_age_has_passed(self) -> None:
        from unittest.mock import patch

        auth = _create_authenticator()
        mock_client = _discovery_client("max-age=100")
        auth.set_api_client(mock_client)
        module = "petstore_client.auth.oauth.openid_connect_authenticator.time"

        with patch(module) as clock:
            clock.monotonic.return_value = 1000.0
            auth.build_authorization_url()
            clock.monotonic.return_value = 1099.0
            auth.build_authorization_url()
            assert mock_client.send_request.call_count == 1

            clock.monotonic.return_value = 1100.0
            auth.build_authorization_url()

        assert mock_client.send_request.call_count == 2

